from pathlib import Path
from unittest.mock import patch
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'container'))
import photo_motion_profile as p
import aerial_opening_profile as a
import renderer
from compose import QualityError
from tests import test_photo_motion_profile as fixture

class Opening(unittest.TestCase):
 setUp=fixture.PhotoMotionProfile.setUp
 tearDown=fixture.PhotoMotionProfile.tearDown
 task=fixture.PhotoMotionProfile.task
 decode=fixture.PhotoMotionProfile.decode
 def receipt(self,frames=120):
  asset='55555555-5555-4555-8555-555555555555'
  return{'schema':1,'kind':'aerial_opening','aerial_job_id':'66666666-6666-4666-8666-666666666666','asset_id':'77777777-7777-4777-8777-777777777777','provenance_id':'88888888-8888-4888-8888-888888888888','sha256':'e'*64,'bytes':100,'visible_frames':frames,'source':{'photo_asset_id':asset,'photo_version_id':'asset:'+asset,'photo_provenance_id':None,'sha256':'f'*64,'bytes':100},'position':0,'scope':{'actor_id':'11111111-1111-4111-8111-111111111111','org_id':'22222222-2222-4222-8222-222222222222','selected_library_org_id':'33333333-3333-4333-8333-333333333333','listing_id':'44444444-4444-4444-8444-444444444444'},'fps':24,'available_frames':frames,'width':1080,'height':1920,'duration_s':frames/24,'aspect':'9:16','disclosure':'Drone-style movement is simulated. No drone footage was captured. This establishing shot was generated by AI.','accepted_at':'2026-10-22T00:00:00Z'}
 def opening_task(self):
  t=self.task();r=self.receipt();t.update(composition_profile=p.OPENING_PROFILE,opening={'receipt':r,'media':{'url':'https://media.fixture.invalid/opening','sha256':r['sha256'],'bytes':r['bytes'],'etag':'"opening"'}});return t
 def test_closed_reference_media_scope_full_frames_and_no_plain_v2_bypass(self):
  original=self.opening_task();renderer.validate_task(original)
  for frames in [120,121,144,192]:
   t=copy.deepcopy(original);r=t['opening']['receipt'];r.update(visible_frames=frames,available_frames=frames,duration_s=frames/24);renderer.validate_task(t)
  variants=[]
  for field,value in [('position',1),('fps',30),('available_frames',144),('visible_frames',48),('width',1920),('duration_s',4),('asset_id','not-an-id'),('accepted_at','today'),('accepted',True),('bytes',134217729)]:
   t=copy.deepcopy(original);t['opening']['receipt'][field]=value;variants.append(t)
  for field,value in [('sha256','a'*64),('bytes',101),('etag',''),('extra',True)]:
   t=copy.deepcopy(original);t['opening']['media'][field]=value;variants.append(t)
  for field,value in [('photo_version_id','prepared:wrong'),('bytes',True),('photo_provenance_id','missing')]:
   t=copy.deepcopy(original);t['opening']['receipt']['source'][field]=value;variants.append(t)
  t=copy.deepcopy(original);t['opening']['receipt']['scope']['extra']=True;variants.append(t)
  t=copy.deepcopy(original);del t['opening'];variants.append(t)
  t=copy.deepcopy(original);t['composition_profile']=p.PROFILE;variants.append(t)
  for t in variants:
   with self.subTest(t=t),self.assertRaises((QualityError,ValueError,KeyError)):renderer.validate_task(t)
 def test_audio_uses_full_timeline_without_extra_opening_or_tail(self):
  t=self.opening_task()
  for key in ['purpose','aspect','sources','presentation','narration','music','output','opening']:t.pop(key)
  t.update(action='inspect_audio',max_duration_s=7,source={'url':'https://media.fixture.invalid/audio','sha256':'b'*64,'bytes':100,'etag':'"audio"'})
  renderer.validate_task(t)
  for duration in [True,6,508.01]:
   with self.assertRaises(QualityError):renderer.validate_task({**t,'max_duration_s':duration})
  with self.assertRaises(QualityError):renderer.validate_task({**t,'opening':self.receipt()})
 def encode_opening(self,path,rate=24):
  subprocess.run(['ffmpeg','-v','error','-nostdin','-y','-f','lavfi','-i',f'testsrc2=size=1080x1920:rate={rate}:duration=5','-an','-vf','setparams=color_primaries=bt709:color_trc=bt709:colorspace=bt709','-c:v','libx264','-preset','ultrafast','-crf','18','-threads','2','-pix_fmt','yuv420p','-color_primaries','bt709','-color_trc','bt709','-colorspace','bt709','-video_track_timescale','24000',str(path)],check=True)
 def test_actual_first_full_clip_then_exact_photo_motion_and_first_poster(self):
  source=self.root/'opening-source.mp4';self.encode_opening(source);source_sha=hashlib.sha256(source.read_bytes()).hexdigest();t=self.opening_task();r=t['opening']['receipt'];r.update(sha256=source_sha,bytes=source.stat().st_size);t['opening']['media'].update(sha256=source_sha,bytes=source.stat().st_size)
  def read(d,target,hosts,**kw):
   self.assertEqual(hosts,{'media.fixture.invalid'});src=source if d['url'].endswith('/opening') else self.photo
   self.assertEqual(d['sha256'],hashlib.sha256(src.read_bytes()).hexdigest());self.assertEqual(d['bytes'],src.stat().st_size);shutil.copyfile(src,target);return d['sha256']
  with patch.object(a,'download',side_effect=read),patch.object(renderer.shutil,'rmtree'):
   out=renderer.render(t,{'media.fixture.invalid'},str(self.root))['result']
  facts=p.probe(out['master']);p.require_cfr24(out['master'],facts,exact_frames={168});self.assertEqual(float(facts['format']['duration']),7);self.assertEqual(len(facts['streams']),1)
  self.assertEqual(out['receipt']['opening'],r);self.assertEqual(out['receipt']['total_frames'],168);self.assertEqual(out['receipt']['source_frames'],[48]);self.assertEqual(out['receipt']['source_sha256s'],[self.input_sha]);self.assertEqual(out['receipt']['composition_profile'],p.OPENING_PROFILE)
  decoded=self.decode(out['master'],[0,119,120,167]);expected=self.decode(source,[0,119]);errors=[float(np.mean(np.abs(x.astype(float)-y.astype(float))))for x,y in zip(decoded[:2],expected)]
  self.assertTrue(all(x<5 for x in errors),('opening pixels/frame bounds',errors));self.assertGreater(float(np.mean(np.abs(decoded[1].astype(float)-decoded[2].astype(float)))),20,'opening must precede photo at exact frame120')
  from PIL import Image
  poster=np.asarray(Image.open(out['poster']).convert('RGB'));self.assertLess(float(np.mean(np.abs(poster.astype(float)-decoded[0].astype(float)))),5,'poster must come from first aerial frame')
  self.assertEqual(hashlib.sha256(source.read_bytes()).hexdigest(),source_sha);self.assertEqual(hashlib.sha256(self.photo.read_bytes()).hexdigest(),self.input_sha)
  (self.root/'actual-output-facts.json').write_text(json.dumps({'frames':168,'fps':24,'seconds':7,'photo_frames':[48],'opening_frames':120,'opening_first_last_mean_absolute_rgb_error':errors,'opening_input_sha_unchanged':source_sha,'photo_input_sha_unchanged':self.input_sha,'output_sha256':hashlib.sha256(out['master'].read_bytes()).hexdigest()},indent=2)+'\n')
 def test_actual_wrong_cadence_refuses_instead_of_retime(self):
  source=self.root/'wrong30fps.mp4';self.encode_opening(source,30)
  with self.assertRaisesRegex(QualityError,'native_cfr24'):a.verified_opening_clip(source,self.receipt(),self.root/'must-not-exist.mp4')
  self.assertFalse((self.root/'must-not-exist.mp4').exists())

if __name__=='__main__':unittest.main()

class Full121Opening(unittest.TestCase):
 setUp=Opening.setUp
 tearDown=Opening.tearDown
 task=Opening.task
 receipt=Opening.receipt
 decode=Opening.decode
 opening_task=Opening.opening_task
 def test_full121_opening_then_photos_keeps169frames(self):
  source=self.root/'opening121.mp4';subprocess.run(['ffmpeg','-v','error','-nostdin','-y','-f','lavfi','-i','testsrc2=size=1080x1920:rate=24','-frames:v','121','-an','-vf','setparams=color_primaries=bt709:color_trc=bt709:colorspace=bt709','-c:v','libx264','-preset','ultrafast','-crf','18','-threads','2','-pix_fmt','yuv420p',str(source)],check=True);sha=hashlib.sha256(source.read_bytes()).hexdigest();t=self.opening_task();r=self.receipt(121);r.update(sha256=sha,bytes=source.stat().st_size);t['opening']={'receipt':r,'media':{'url':'https://media.fixture.invalid/opening','sha256':sha,'bytes':source.stat().st_size,'etag':'exact'}}
  def read(d,target,hosts,**kw):
   src=source if d['url'].endswith('/opening')else self.photo;self.assertEqual(d['sha256'],hashlib.sha256(src.read_bytes()).hexdigest());shutil.copyfile(src,target);return d['sha256']
  with patch.object(a,'download',side_effect=read):out=renderer.render(t,{'media.fixture.invalid'},str(self.root))['result']
  facts=p.probe(out['master']);p.require_cfr24(out['master'],facts,exact_frames={169});self.assertAlmostEqual(float(facts['format']['duration']),169/24,places=5);self.assertEqual(out['receipt']['total_frames'],169);self.assertEqual(out['receipt']['opening']['visible_frames'],121);self.assertEqual(out['receipt']['source_frames'],[48]);actual=self.decode(out['master'],[120,121]);last=self.decode(source,[120])[0];self.assertLess(float(np.mean(np.abs(actual[0].astype(float)-last.astype(float)))),5);self.assertGreater(float(np.mean(np.abs(actual[0].astype(float)-actual[1].astype(float)))),20);self.assertEqual(hashlib.sha256(source.read_bytes()).hexdigest(),sha)
